]

# Find all non-background positions
positions = {}
for r in range(len(grid)):
    for c in range(len(grid[r])):
        if grid[r][c] != 9:
            if grid[r][c] not in positions:
                positions[grid[r][c]] = []
            positions[grid[r][c]].append((r, c))

print("Color counts:")
for color, pos in sorted(positions.items()):
    print(f"  {color}: count={len(pos)}, positions={pos}")

# Analyze horizontal neighbors for 8s
print("\nChecking if 8s can connect horizontally:")
import numpy as np
grid_arr = np.array(grid)

# For each non-9 cell, check if it connects to another non-9 cell
for color, pos in positions.items():
    print(f"\n{color} connectivity:")
    for r, c in pos:
        neighbors = []
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if grid[nr][nc] == color:
                    neighbors.append((nr, nc))
        if neighbors:
            print(f"  ({r},{c}) connected to: {neighbors}")

